import{_ as e,o as a,c as r,Q as o}from"./chunks/framework.5916b37e.js";const b=JSON.parse('{"title":"Interface: optsType","description":"","frontmatter":{},"headers":[],"relativePath":"apidist/interfaces/Loader_copperNrrdLoader.optsType.md","filePath":"apidist/interfaces/Loader_copperNrrdLoader.optsType.md"}'),t={name:"apidist/interfaces/Loader_copperNrrdLoader.optsType.md"},n=o('<p><a href="./../README.html">copper3d</a> / <a href="./../modules.html">Modules</a> / <a href="./../modules/Loader_copperNrrdLoader.html">Loader/copperNrrdLoader</a> / optsType</p><h1 id="interface-optstype" tabindex="-1">Interface: optsType <a class="header-anchor" href="#interface-optstype" aria-label="Permalink to &quot;Interface: optsType&quot;">​</a></h1><p><a href="./../modules/Loader_copperNrrdLoader.html">Loader/copperNrrdLoader</a>.optsType</p><h2 id="table-of-contents" tabindex="-1">Table of contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of contents&quot;">​</a></h2><h3 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h3><ul><li><a href="./Loader_copperNrrdLoader.optsType.html#axes">axes</a></li><li><a href="./Loader_copperNrrdLoader.optsType.html#container">container</a></li><li><a href="./Loader_copperNrrdLoader.optsType.html#knownminmax">knownMinMax</a></li><li><a href="./Loader_copperNrrdLoader.optsType.html#onerror">onError</a></li><li><a href="./Loader_copperNrrdLoader.optsType.html#onprogress">onProgress</a></li><li><a href="./Loader_copperNrrdLoader.optsType.html#opengui">openGui</a></li><li><a href="./Loader_copperNrrdLoader.optsType.html#signal">signal</a></li></ul><h2 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="axes" tabindex="-1">axes <a class="header-anchor" href="#axes" aria-label="Permalink to &quot;axes&quot;">​</a></h3><p>• <code>Optional</code> <strong>axes</strong>: readonly <a href="./../modules/Loader_copperNrrdLoader.html#nrrdaxis"><code>NrrdAxis</code></a>[]</p><p>Which slice planes to extract. Defaults to all three, i.e. exactly what previous versions did.</p><p>Narrow it when you display fewer. <code>extractSlice</code> walks the whole volume per call and the result is retained on <code>volume.sliceList</code> for the volume&#39;s lifetime, so an axis you never show costs a full pass over a 50MB buffer plus a geometry, a material and a canvas-backed texture that nothing ever frees.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The omitted axes are <code>undefined</code> on the <code>nrrdMeshes</code> / <code>nrrdSlices</code> the callback receives. Their types still declare all three present -- widening them to optional would break every existing caller&#39;s compile -- so a caller that narrows <code>axes</code> is responsible for only reading what it asked for.</p></div><h4 id="defined-in" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L240" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:240</a></p><hr><h3 id="container" tabindex="-1">container <a class="header-anchor" href="#container" aria-label="Permalink to &quot;container&quot;">​</a></h3><p>• <code>Optional</code> <strong>container</strong>: <code>HTMLDivElement</code></p><h4 id="defined-in-1" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-1" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L221" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:221</a></p><hr><h3 id="knownminmax" tabindex="-1">knownMinMax <a class="header-anchor" href="#knownminmax" aria-label="Permalink to &quot;knownMinMax&quot;">​</a></h3><p>• <code>Optional</code> <strong>knownMinMax</strong>: [<code>number</code>, <code>number</code>]</p><p>The volume&#39;s whole-intensity <code>[min, max]</code>, already known (e.g. from the backend&#39;s <code>/files/{case_id}/headers</code>, which reads it once from the same bytes the backend already decompresses). When supplied, <code>Volume.computeMinMax()</code> uses it instead of scanning every voxel in the browser -- the single largest function in a case-load CPU profile. Omit it (or pass a stale/wrong-looking one) and behaviour is exactly as before: three&#39;s own scan runs and the image comes out identical, just slower.</p><h4 id="defined-in-2" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-2" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L264" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:264</a></p><hr><h3 id="onerror" tabindex="-1">onError <a class="header-anchor" href="#onerror" aria-label="Permalink to &quot;onError&quot;">​</a></h3><p>• <code>Optional</code> <strong>onError</strong>: (<code>error</code>: <code>unknown</code>) =&gt; <code>void</code></p><h4 id="type-declaration" tabindex="-1">Type declaration <a class="header-anchor" href="#type-declaration" aria-label="Permalink to &quot;Type declaration&quot;">​</a></h4><p>▸ (<code>error</code>): <code>void</code></p><p>Fetch or parse failure. New in 3.9.0; there was no error channel at all before, so a failed volume was indistinguishable from a slow one and the <code>callback</code> simply never fired.</p><h5 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h5><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>error</code></td><td style="text-align:left;"><code>unknown</code></td></tr></tbody></table><h5 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h5><p><code>void</code></p><h4 id="defined-in-3" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-3" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L255" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:255</a></p><hr><h3 id="onprogress" tabindex="-1">onProgress <a class="header-anchor" href="#onprogress" aria-label="Permalink to &quot;onProgress&quot;">​</a></h3><p>• <code>Optional</code> <strong>onProgress</strong>: (<code>event</code>: <code>ProgressEvent</code>&lt;<code>EventTarget</code>&gt;) =&gt; <code>void</code></p><h4 id="type-declaration-1" tabindex="-1">Type declaration <a class="header-anchor" href="#type-declaration-1" aria-label="Permalink to &quot;Type declaration&quot;">​</a></h4><p>▸ (<code>event</code>): <code>void</code></p><p>Download progress, in ADDITION to the built-in loading bar -- that keeps writing its percentage into <code>loadingBar.progress</code> exactly as before.</p><p>New in 3.9.0. Until then the loading bar&#39;s text was the only progress signal copper3d exposed, so a caller that needed to know a large download was still alive had to watch that DOM node for mutations.</p><h5 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h5><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>event</code></td><td style="text-align:left;"><code>ProgressEvent</code>&lt;<code>EventTarget</code>&gt;</td></tr></tbody></table><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h5><p><code>void</code></p><h4 id="defined-in-4" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-4" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L249" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:249</a></p><hr><h3 id="opengui" tabindex="-1">openGui <a class="header-anchor" href="#opengui" aria-label="Permalink to &quot;openGui&quot;">​</a></h3><p>• <strong>openGui</strong>: <code>boolean</code></p><h4 id="defined-in-5" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-5" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L220" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:220</a></p><hr><h3 id="signal" tabindex="-1">signal <a class="header-anchor" href="#signal" aria-label="Permalink to &quot;signal&quot;">​</a></h3><p>• <code>Optional</code> <strong>signal</strong>: <code>AbortSignal</code></p><p>Aborts the in-flight fetch. A superseded load (case switch, series switch) can now stop its transfer instead of only having its eventual result discarded -- see <code>abandonLoad</code> in <code>LeftPanelCore.vue</code>. <code>onError</code> still fires for an aborted fetch (the browser rejects it like any other failed fetch); callers that already ignore errors from a stale load need no further change.</p><h4 id="defined-in-6" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-6" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/e1f17ba/src/Loader/copperNrrdLoader.ts#L272" target="_blank" rel="noreferrer">src/Loader/copperNrrdLoader.ts:272</a></p>',61),d=[n];function i(s,l,c,p,h,f){return a(),r("div",null,d)}const m=e(t,[["render",i]]);export{b as __pageData,m as default};
